// ST GAMES: THE PARADISE - Real Paradise Character Sprite Renderer
window.ParadiseCharacters = {
  images: {},
  embeddedData: {"tribal": "data:image/png;base64,", "crow": "data:image/png;base64,", "dog": "data:image/png;base64,", "rebel": "data:image/png;base64,", "leader": "data:image/png;base64,", "mother": "data:image/png;base64,", "baby": "data:image/png;base64,", "guard_pistol": "data:image/png;base64,", "guard_bazooka": "data:image/png;base64,"},

  initSprites() {
    Object.keys(this.embeddedData).forEach((key) => {
      const img = new Image();
      img.src = this.embeddedData[key];
      this.images[key] = img;
    });
  },

  drawVillager(ctx, v, time, isCarrier) {
    ctx.save();
    ctx.translate(v.x, v.y);

    const isMoving = Math.hypot(v.vx || 0, v.vy || 0) > 1;
    const walkBob = isMoving ? Math.abs(Math.sin(time * 6 + v.seed)) * 2.0 : Math.sin(time * 2.5 + v.seed) * 0.8;
    const tilt = isMoving ? Math.sin(time * 6 + v.seed) * 0.025 : 0;

    // Compact ground ring under active carrier (matches video proportions)
    if (isCarrier) {
      ctx.save();
      ctx.strokeStyle = '#2a9d8f';
      ctx.lineWidth = 2.0;
      ctx.beginPath();
      ctx.ellipse(0, 21, 14, 5, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(42, 157, 143, 0.42)';
      ctx.lineWidth = 1.3;
      ctx.beginPath();
      ctx.ellipse(0, 21, 18, 6.8, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    } else {
      ctx.fillStyle = 'rgba(15, 23, 42, 0.14)';
      ctx.beginPath();
      ctx.ellipse(0, 20, 11, 3.8, 0, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.save();
    ctx.translate(0, -walkBob);
    ctx.rotate(tilt);

    const img = this.images[v.id];
    if (img && img.complete && img.naturalWidth > 0) {
      // Scaled slightly smaller so the notebook page & map feel much bigger!
      const targetH = v.id === 'dog' ? 35 : v.id === 'crow' ? 40 : 50;
      const scale = targetH / img.naturalHeight;
      const drawW = img.naturalWidth * scale;
      const drawH = targetH;
      ctx.drawImage(img, -drawW / 2, -drawH / 2 - 2, drawW, drawH);
    }

    if (isCarrier) {
      this.drawBabyBundle(ctx, 2, 2);
    }

    ctx.restore();
    ctx.restore();
  },

  drawBabyBundle(ctx, x, y) {
    ctx.save();
    ctx.translate(x, y);
    const babyImg = this.images['baby'];
    if (babyImg && babyImg.complete && babyImg.naturalWidth > 0) {
      const w = 28;
      const h = (babyImg.naturalHeight / babyImg.naturalWidth) * w;
      ctx.drawImage(babyImg, -w / 2, -h / 2, w, h);
    } else {
      ctx.fillStyle = '#7dd3fc';
      ctx.strokeStyle = '#0284c7';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.ellipse(0, 0, 10, 6.5, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
    ctx.restore();
  },

  drawGuard(ctx, g, time, targetPos) {
    if (!g.active) return;
    ctx.save();
    ctx.translate(g.x, g.y);
    const bob = Math.abs(Math.sin(time * 9 + g.seed)) * 2.2;
    const facingRight = !targetPos || targetPos.x >= g.x;

    ctx.fillStyle = 'rgba(15, 23, 42, 0.16)';
    ctx.beginPath();
    ctx.ellipse(0, 21, 11, 3.8, 0, 0, Math.PI * 2);
    ctx.fill();

    if (!facingRight) ctx.scale(-1, 1);
    ctx.translate(0, -bob);

    const spriteKey = g.weapon === 'bazooka' ? 'guard_bazooka' : 'guard_pistol';
    const img = this.images[spriteKey];
    if (img && img.complete && img.naturalWidth > 0) {
      const targetH = 52;
      const scale = targetH / img.naturalHeight;
      const drawW = img.naturalWidth * scale;
      ctx.drawImage(img, -drawW / 2, -targetH / 2 - 2, drawW, targetH);
    }
    ctx.restore();
  }
};
